/* v62 — الأذان والإشعارات */
const KEY="BBryBL4-vPUiJfuOZGWBXOEawUBZ6TJfXuEiEyRJ3i-CgfbN7OS_iTfYA_EQgf-EZls4kx4xYiMGbHJe0bYyddU";
