 const chk=()=>navigator.serviceWorker.getRegistration().then(r=>{if(!r)return;r.update().catch(()=>{});if(r.waiting&&navigator.serviceWorker.controller)r.waiting.postMessage&&r.waiting.postMessage("skip")}).catch(()=>{});
