var K=[
{id:"fil",title:"عامُ الفيل",sub:"كيف حمى اللهُ بيتَه الحرام",scenes:[
["f1","الكنيسةُ الكبيرة","مِنْ زَمَنٍ بَعِيدٍ، كَانَ فِي بِلَادِ الْيَمَنِ حَاكِمٌ اسْمُهُ «أَبْرَهَةُ». وَكَانَ يَرَى النَّاسَ يَأْتُونَ مِنْ كُلِّ مَكَانٍ إِلَى «الْكَعْبَةِ» فِي «مَكَّةَ»، فَغَارَ وَحَسَدَهُمْ. فَبَنَى فِي «صَنْعَاءَ» كَنِيسَةً كَبِيرَةً جَمِيلَةً، وَقَالَ: «سَأَجْعَلُ النَّاسَ يَحُجُّونَ إِلَى هُنَا!» لَكِنَّ الْعَرَبَ لَمْ يَتْرُكُوا الْكَعْبَةَ، فَهِيَ أَوَّلُ بَيْتٍ بُنِيَ لِعِبَادَةِ اللهِ، بَنَاهُ إِبْرَاهِيمُ وَإِسْمَاعِيلُ عَلَيْهِمَا السَّلَامُ."],
["f2","الجيشُ والفيل","غَضِبَ أَبْرَهَةُ غَضَبًا شَدِيدًا، وَقَرَّرَ أَنْ يَهْدِمَ الْكَعْبَةَ! فَجَمَعَ جَيْشًا كَبِيرًا، وَمَعَهُ فِيلٌ ضَخْمٌ لَمْ يَرَ الْعَرَبُ مِثْلَهُ مِنْ قَبْلُ. وَسَارَ الْجَيْشُ أَيَّامًا طَوِيلَةً فِي الصَّحْرَاءِ، حَتَّى اقْتَرَبَ مِنْ مَكَّةَ."],
["f3","«لِلبَيْتِ رَبٌّ يَحْمِيهِ»","أَخَذَ جُنْدُ أَبْرَهَةَ إِبِلًا كَثِيرَةً مِنْ أَهْلِ مَكَّةَ، مِنْهَا إِبِلٌ لِسَيِّدِ مَكَّةَ «عَبْدِ الْمُطَّلِبِ». فَذَهَبَ عَبْدُ الْمُطَّلِبِ إِلَى أَبْرَهَةَ، وَطَلَبَ إِبِلَهُ. تَعَجَّبَ أَبْرَهَةُ وَقَالَ: «تَسْأَلُنِي عَنِ الْإِبِلِ، وَلَا تَسْأَلُنِي عَنِ الْكَعْبَةِ!» فَقَالَ عَبْدُ الْمُطَّلِبِ بِثِقَةٍ: «أَنَا رَبُّ الْإِبِلِ، وَلِلْبَيْتِ رَبٌّ يَحْمِيهِ.»"],
["f4","الفيلُ يرفُض","فِي الصَّبَاحِ، أَمَرَ أَبْرَهَةُ جَيْشَهُ أَنْ يَتَقَدَّمَ نَحْوَ الْكَعْبَةِ. لَكِنَّ الْفِيلَ بَرَكَ عَلَى الْأَرْضِ، وَرَفَضَ أَنْ يَمْشِيَ إِلَى مَكَّةَ! فَإِذَا وَجَّهُوهُ إِلَى أَيِّ جِهَةٍ أُخْرَى قَامَ وَمَشَى، وَإِذَا وَجَّهُوهُ إِلَى الْكَعْبَةِ بَرَكَ مِنْ جَدِيدٍ."],
["f5","الطيرُ الأبابيل","وَفَجْأَةً، امْتَلَأَتِ السَّمَاءُ بِطُيُورٍ صَغِيرَةٍ تَأْتِي أَسْرَابًا أَسْرَابًا. فِي مِنْقَارِ كُلِّ طَائِرٍ حَجَرٌ صَغِيرٌ، وَفِي رِجْلَيْهِ حَجَرَانِ. رَمَتِ الطُّيُورُ الْجَيْشَ بِالْحِجَارَةِ، فَهَلَكُوا وَلَمْ يَبْلُغُوا الْكَعْبَةَ. وَنَجَّى اللهُ بَيْتَهُ، كَمَا قَالَ عَبْدُ الْمُطَّلِبِ."],
["f6","المولودُ المبارك","وَفِي هَذَا الْعَامِ نَفْسِهِ، الَّذِي سَمَّاهُ النَّاسُ «عَامَ الْفِيلِ»، وُلِدَ فِي مَكَّةَ طِفْلٌ مُبَارَكٌ. إِنَّهُ مُحَمَّدٌ ﷺ، الَّذِي أَرْسَلَهُ اللهُ بَعْدَ ذَلِكَ رَحْمَةً لِلْعَالَمِينَ."]],
learn:["اللهُ يَحْمِي بَيْتَهُ، وَلَا يَغْلِبُهُ أَحَدٌ.","الْحَسَدُ وَالظُّلْمُ نِهَايَتُهُمَا خَسَارَةٌ."],
quiz:[["مَاذَا فَعَلَ الْفِيلُ عِنْدَمَا وَجَّهُوهُ إِلَى الْكَعْبَةِ؟",["بَرَكَ وَرَفَضَ","مَشَى مُسْرِعًا","عَادَ إِلَى الْيَمَنِ"],0],["مَنِ الَّذِي وُلِدَ فِي عَامِ الْفِيلِ؟",["مُحَمَّدٌ ﷺ","إِبْرَاهِيمُ","مُوسَى"],0]],
src:"سورة الفيل (١–٥)؛ سيرة ابن هشام؛ صحيح البخاري: «حَبَسَهَا حَابِسُ الْفِيلِ»."},
{id:"yatim",title:"اليتيمُ الكريم",sub:"طفولةُ النبيّ ﷺ",scenes:[
["y1","مُحَمَّد","كَانَ أَبُو النَّبِيِّ ﷺ اسْمُهُ «عَبْدُ اللهِ»، وَأُمُّهُ اسْمُهَا «آمِنَةُ». سَافَرَ عَبْدُ اللهِ فِي رِحْلَةٍ، فَمَرِضَ وَمَاتَ قَبْلَ أَنْ يُولَدَ ابْنُهُ. فَلَمَّا وُلِدَ الْمَوْلُودُ، فَرِحَ بِهِ جَدُّهُ «عَبْدُ الْمُطَّلِبِ» فَرَحًا شَدِيدًا، وَسَمَّاهُ: «مُحَمَّدًا»."],
["y2","في البادية","كَانَ أَهْلُ مَكَّةَ يُرْسِلُونَ أَطْفَالَهُمْ إِلَى الْبَادِيَةِ، لِيَنْمُوا أَقْوِيَاءَ فِي الْهَوَاءِ النَّقِيِّ. فَأَخَذَتْ مُحَمَّدًا امْرَأَةٌ طَيِّبَةٌ اسْمُهَا «حَلِيمَةُ السَّعْدِيَّةُ» لِتُرْضِعَهُ. وَمُنْذُ أَنْ دَخَلَ بَيْتَهَا، مَلَأَتِ الْبَرَكَةُ كُلَّ شَيْءٍ: سَمِنَتِ الْغَنَمُ، وَكَثُرَ اللَّبَنُ، وَفَرِحَتْ حَلِيمَةُ بِهِ كَثِيرًا."],
["y3","وداعًا يا أُمّي","عَادَ مُحَمَّدٌ إِلَى أُمِّهِ آمِنَةَ، وَعَاشَ مَعَهَا فِي مَكَّةَ. وَلَمَّا كَانَ عُمُرُهُ سِتَّ سَنَوَاتٍ، سَافَرَتْ بِهِ إِلَى الْمَدِينَةِ لِيَزُورَ أَخْوَالَ جَدِّهِ. وَفِي طَرِيقِ الْعَوْدَةِ، فِي مَكَانٍ اسْمُهُ «الْأَبْوَاءِ»، مَرِضَتْ آمِنَةُ وَمَاتَتْ. فَصَارَ مُحَمَّدٌ ﷺ يَتِيمًا، بِلَا أَبٍ وَلَا أُمٍّ."],
["y4","الجدُّ ثمّ العمّ","أَخَذَهُ جَدُّهُ عَبْدُ الْمُطَّلِبِ، وَأَحَبَّهُ حُبًّا كَبِيرًا، وَكَانَ يُجْلِسُهُ بِجَانِبِهِ. وَلَمَّا بَلَغَ مُحَمَّدٌ ثَمَانِيَ سَنَوَاتٍ، مَاتَ الْجَدُّ. فَكَفَلَهُ عَمُّهُ «أَبُو طَالِبٍ»، وَكَانَ يُحِبُّهُ أَكْثَرَ مِنْ أَوْلَادِهِ."],
["y5","الصّادقُ الأمين","كَبِرَ مُحَمَّدٌ ﷺ، وَكَانَ لَا يَكْذِبُ أَبَدًا، وَيُعِيدُ الْأَمَانَاتِ إِلَى أَصْحَابِهَا. حَتَّى صَارَ أَهْلُ مَكَّةَ كُلُّهُمْ يُسَمُّونَهُ: «الصَّادِقَ الْأَمِينَ». وَهَكَذَا رَعَى اللهُ هَذَا الْيَتِيمَ، كَمَا قَالَ فِي الْقُرْآنِ: ﴿أَلَمْ يَجِدْكَ يَتِيمًا فَآوَى﴾."]],
learn:["نَرْحَمُ الْيَتِيمَ وَنُحْسِنُ إِلَيْهِ، كَمَا أَحْسَنَ الْجَدُّ وَالْعَمُّ إِلَى النَّبِيِّ ﷺ.","الصِّدْقُ وَالْأَمَانَةُ يَجْعَلَانِ النَّاسَ يُحِبُّونَكَ وَيَثِقُونَ بِكَ."],
quiz:[["مَا اسْمُ الَّتِي أَرْضَعَتِ النَّبِيَّ ﷺ فِي الْبَادِيَةِ؟",["حَلِيمَةُ","آمِنَةُ","خَدِيجَةُ"],0],["بِمَاذَا كَانَ أَهْلُ مَكَّةَ يُسَمُّونَهُ؟",["الصَّادِقَ الْأَمِينَ","الْمَلِكَ","الْفَارِسَ"],0]],
src:"سورة الضحى (٦)؛ سيرة ابن هشام؛ مسند أحمد في قصة وضع الحجر الأسود: «هَذَا الْأَمِينُ»."},
{id:"wudu-k",title:"كيف أتوضّأ؟",sub:"خطوة بخطوة مثل النبيّ ﷺ",scenes:[
["w1","أستعدّ للوضوء","الْوُضُوءُ نَظَافَةٌ وَنُورٌ، وَهُوَ قَبْلَ الصَّلَاةِ. أَنْوِي فِي قَلْبِي أَنِّي أَتَوَضَّأُ لِأُصَلِّيَ، وَأَفْتَحُ الْمَاءَ قَلِيلًا، فَلَا أُسْرِفُ فِي الْمَاءِ."],
["w2","أقول: بسم الله","قَبْلَ أَنْ أَبْدَأَ أَقُولُ: «بِسْمِ اللهِ»."],
["w3","أغسل كفّيّ","أَغْسِلُ كَفَّيَّ ثَلَاثَ مَرَّاتٍ، وَأُدْخِلُ الْمَاءَ بَيْنَ أَصَابِعِي."],
["w4","المضمضة والاستنشاق","آخُذُ الْمَاءَ بِيَدِي الْيُمْنَى فَأَتَمَضْمَضُ، ثُمَّ أَسْتَنْشِقُ الْمَاءَ بِأَنْفِي وَأُخْرِجُهُ. ثَلَاثَ مَرَّاتٍ."],
["w5","أغسل وجهي ويديّ","أَغْسِلُ وَجْهِي ثَلَاثَ مَرَّاتٍ. ثُمَّ أَغْسِلُ يَدِي الْيُمْنَى إِلَى الْمِرْفَقِ ثَلَاثًا، ثُمَّ الْيُسْرَى ثَلَاثًا."],
["w6","أمسح رأسي وأذنيّ","أَبُلُّ يَدَيَّ، وَأَمْسَحُ رَأْسِي مِنَ الْأَمَامِ إِلَى الْخَلْفِ ثُمَّ أَرْجِعُ، ثُمَّ أَمْسَحُ أُذُنَيَّ. مَرَّةً وَاحِدَةً."],
["w7","أغسل رجليّ","أَغْسِلُ رِجْلِي الْيُمْنَى إِلَى الْكَعْبَيْنِ ثَلَاثًا، ثُمَّ الْيُسْرَى ثَلَاثًا، وَلَا أَنْسَى مَا بَيْنَ الْأَصَابِعِ."],
["w8","دعاء بعد الوضوء","أَقُولُ: «أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ». أَحْسَنْتَ! الْآنَ أَنْتَ جَاهِزٌ لِلصَّلَاةِ."]],
learn:["الْوُضُوءُ يَبْدَأُ بِالْيَمِينِ.","لَا نُسْرِفُ فِي الْمَاءِ وَلَوْ كَانَ كَثِيرًا."],
quiz:[["مَاذَا نَقُولُ قَبْلَ الْوُضُوءِ؟",["بِسْمِ اللهِ","اللهُ أَكْبَرُ","الْحَمْدُ لِلَّهِ"],0],["نَمْسَحُ الرَّأْسَ كَمْ مَرَّةً؟",["مَرَّةً وَاحِدَةً","ثَلَاثَ مَرَّاتٍ","خَمْسَ مَرَّاتٍ"],0],["بِأَيِّ يَدٍ نَبْدَأُ؟",["الْيُمْنَى","الْيُسْرَى"],0]],
src:"صفة وضوء النبي ﷺ: البخاري ١٥٩ و١٨٥، ومسلم ٢٢٦؛ الدعاء: مسلم ٢٣٤؛ التسمية: أبو داود ١٠١."},
{id:"salah-k",title:"كيف أصلّي؟",sub:"صلاةُ ركعتين مثل الفجر",scenes:[
["p1","أتّجه إلى القبلة","بَعْدَ الْوُضُوءِ، أَقِفُ عَلَى سَجَّادَتِي وَوَجْهِي إِلَى الْقِبْلَةِ، نَحْوَ الْكَعْبَةِ فِي مَكَّةَ. وَأَنْوِي فِي قَلْبِي الصَّلَاةَ."],
["p2","الله أكبر","أَرْفَعُ يَدَيَّ وَأَقُولُ: «اللهُ أَكْبَرُ»، ثُمَّ أَضَعُ يَدِي الْيُمْنَى عَلَى الْيُسْرَى عَلَى صَدْرِي."],
["p3","أقرأ الفاتحة","أَقْرَأُ سُورَةَ الْفَاتِحَةِ، ثُمَّ أَقْرَأُ سُورَةً قَصِيرَةً أَحْفَظُهَا، مِثْلَ سُورَةِ الْإِخْلَاصِ."],
["p4","أركع","أَقُولُ: «اللهُ أَكْبَرُ» وَأَرْكَعُ، يَدَايَ عَلَى رُكْبَتَيَّ وَظَهْرِي مُسْتَقِيمٌ، وَأَقُولُ ثَلَاثًا: «سُبْحَانَ رَبِّيَ الْعَظِيمِ». ثُمَّ أَقُومُ وَأَقُولُ: «سَمِعَ اللهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ»."],
["p5","أسجد","أَقُولُ: «اللهُ أَكْبَرُ» وَأَسْجُدُ، جَبْهَتِي وَأَنْفِي وَكَفَّايَ وَرُكْبَتَايَ وَأَصَابِعُ قَدَمَيَّ عَلَى الْأَرْضِ، وَأَقُولُ ثَلَاثًا: «سُبْحَانَ رَبِّيَ الْأَعْلَى». ثُمَّ أَجْلِسُ وَأَقُولُ: «رَبِّ اغْفِرْ لِي»، ثُمَّ أَسْجُدُ مَرَّةً ثَانِيَةً. هَذِهِ رَكْعَةٌ! ثُمَّ أَقُومُ لِلرَّكْعَةِ الثَّانِيَةِ وَأُصَلِّيهَا مِثْلَ الْأُولَى."],
["p6","أجلس للتشهّد","بَعْدَ الرَّكْعَةِ الثَّانِيَةِ أَجْلِسُ وَأَقْرَأُ التَّشَهُّدَ: «التَّحِيَّاتُ لِلَّهِ...»، ثُمَّ أُصَلِّي عَلَى النَّبِيِّ ﷺ."],
["p7","أسلّم","أَلْتَفِتُ إِلَى الْيَمِينِ وَأَقُولُ: «السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ»، ثُمَّ إِلَى الْيَسَارِ وَأَقُولُ مِثْلَهَا. أَحْسَنْتَ! صَلَّيْتَ رَكْعَتَيْنِ."],
["p8","عدد الركعات","الْفَجْرُ رَكْعَتَانِ، وَالظُّهْرُ أَرْبَعٌ، وَالْعَصْرُ أَرْبَعٌ، وَالْمَغْرِبُ ثَلَاثٌ، وَالْعِشَاءُ أَرْبَعٌ. خَمْسُ صَلَوَاتٍ كُلَّ يَوْمٍ."]],
learn:["الصَّلَاةُ عَمُودُ الدِّينِ، وَنُصَلِّيهَا فِي وَقْتِهَا.","نَطْمَئِنُّ فِي الصَّلَاةِ وَلَا نَسْتَعْجِلُ."],
quiz:[["مَاذَا نَقُولُ فِي السُّجُودِ؟",["سُبْحَانَ رَبِّيَ الْأَعْلَى","سُبْحَانَ رَبِّيَ الْعَظِيمِ","بِسْمِ اللهِ"],0],["كَمْ رَكْعَةً فِي صَلَاةِ الْمَغْرِبِ؟",["ثَلَاثٌ","رَكْعَتَانِ","أَرْبَعٌ"],0],["إِلَى أَيْنَ نَتَّجِهُ فِي الصَّلَاةِ؟",["إِلَى الْقِبْلَةِ","إِلَى الشُّبَّاكِ","إِلَى أَيِّ مَكَانٍ"],0]],
src:"«صلّوا كما رأيتموني أصلي» البخاري ٦٣١؛ الركوع والسجود: مسلم ٧٧٢؛ الجلسة: أبو داود ٨٧٤؛ التشهد: البخاري ٨٣١."}
];

